 * Aligns two sequences of lines with a longest common subsequence, breaking
 * ties toward the earliest possible matches as specified: walking both
 * sequences from the start, take a match whenever the current lines are
 * equal, and otherwise advance whichever side's remaining subsequence is at
 * least as long as the other's, preferring to advance the base on a tie.
 *
 * Returns the list of matches as `[baseIndex, sideIndex]` pairs, in order.
 */
export function alignLines(base, side) {
  const n = base.length
  const m = side.length

  // suffixLcs[i][j] = length of the LCS of base[i:] and side[j:].
  const suffixLcs = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        suffixLcs[i][j] = suffixLcs[i + 1][j + 1] + 1
      } else {
        const dropBase = suffixLcs[i + 1][j]
        const dropSide = suffixLcs[i][j + 1]
        suffixLcs[i][j] = dropBase >= dropSide ? dropBase : dropSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (suffixLcs[i + 1][j] >= suffixLcs[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}
